def now_utc() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="milliseconds").replace("+00:00", "Z")


def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def stable_id(prefix: str, *parts: str, length: int = 20) -> str:
    canonical = "\x1f".join(str(part).replace("\\", "/") for part in parts)
    return f"{prefix}-{sha256_bytes(canonical.encode('utf-8'))[:length]}"


def graphify_rel(path: Path) -> str:
    return "Graphify/" + path.resolve().relative_to(GRAPHIFY.resolve()).as_posix()


def load_json(path: Path) -> Any:
    return json.loads(path.read_text(encoding="utf-8-sig"))


def load_jsonl(path: Path) -> list[dict[str, Any]]:
    if not path.exists():
        return []
    return [
        json.loads(line)
        for line in path.read_text(encoding="utf-8-sig").splitlines()
        if line.strip()
    ]


def assert_graphify_path(path: Path) -> None:
    resolved = path.resolve()
    if resolved != GRAPHIFY.resolve() and GRAPHIFY.resolve() not in resolved.parents:
        raise RuntimeError(f"Refusing non-Graphify write: {resolved}")


def atomic_write_text(path: Path, text: str) -> None:
    assert_graphify_path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(path.name + ".tmp")
    temporary.write_text(text, encoding="utf-8", newline="\n")
    os.replace(temporary, path)


def write_json(path: Path, value: Any) -> None:
    atomic_write_text(path, json.dumps(value, ensure_ascii=False, indent=2) + "\n")


def write_jsonl(path: Path, rows: Iterable[dict[str, Any]]) -> None:
    atomic_write_text(
        path,
        "".join(
            json.dumps(row, ensure_ascii=False, separators=(",", ":")) + "\n"
            for row in rows
        ),
    )


def copy_file(source: Path, target: Path) -> None:
    assert_graphify_path(target)
    target.parent.mkdir(parents=True, exist_ok=True)
    temporary = target.with_name(target.name + ".tmp")
    shutil.copyfile(source, temporary)
    os.replace(temporary, target)


def source_digest(path_text: str) -> dict[str, Any]:
    path = PROJECT / path_text
    if path.is_file():
        return {
            "path": path_text,
            "pathKind": "FILE",
            "sha256": sha256_file(path),
            "sizeBytes": path.stat().st_size,
        }
    if path.is_dir():
        rows = []
        for item in sorted(p for p in path.rglob("*") if p.is_file()):
            rows.append(
                {
                    "path": item.relative_to(path).as_posix(),
                    "sizeBytes": item.stat().st_size,
                    "sha256": sha256_file(item),
                }
            )
        canonical = "".join(
            f"{row['path']}\0{row['sizeBytes']}\0{row['sha256']}\n" for row in rows
        )
        return {
            "path": path_text,
            "pathKind": "DIRECTORY_ROOT",
            "sha256": sha256_bytes(canonical.encode("utf-8")),
            "fileCount": len(rows),
        }
    raise FileNotFoundError(path)


def require_pre_edit_approval() -> tuple[dict[str, Any], dict[str, Any], dict[str, Any]]:
    manifest = load_json(MANIFEST_PATH)
    baseline = load_json(BASELINE_PATH)
    inventory = load_json(INVENTORY_PATH)
    if manifest["runId"] != RUN_ID or baseline["runId"] != RUN_ID or inventory["runId"] != RUN_ID:
        raise RuntimeError("Product-expansion run ID mismatch")
    if manifest["independentReviewer"]["currentDecision"] not in {
        "APPROVED_PRE_EDIT_INVENTORY",
        "APPROVED_FINAL_FROZEN_SNAPSHOT",
    }:
        raise RuntimeError("Independent pre-edit preservation approval is absent")
    authorised_initial_edit = manifest["mutationInterlocks"][
        "masterPlanMutationAuthorized"
    ]
    authorised_pre_review_regeneration = (
        manifest.get("status")
        in {
            "PRIMARY_ARTIFACTS_GENERATED_PENDING_VALIDATION_AND_REVIEW",
            "PRODUCT_EXPANSION_MAPPING_COMPLETE",
        }
        and all(
            (b":ADDITIVE-PRODUCT-EXPANSION -->" in (PLANS / name).read_bytes() or MARKER.encode("utf-8") in (PLANS / name).read_bytes())
            for name in PLAN_NAMES
        )
    )
    if not (authorised_initial_edit or authorised_pre_review_regeneration):
        raise RuntimeError("Master Plan mutation/regeneration interlock remains locked")
    if manifest["mutationInterlocks"]["codebaseMutationAuthorized"]:
        raise RuntimeError("Codebase mutation must remain forbidden")
    for plan in baseline["originalMasterPlans"]:
        path = PROJECT / plan["path"]
        raw = path.read_bytes()
        prefix_valid = (
            len(raw) >= plan["bytes"]
            and sha256_bytes(raw[: plan["bytes"]]) == plan["sha256"]
        )
        expansion_already_started = b":ADDITIVE-PRODUCT-EXPANSION -->" in raw or MARKER.encode("utf-8") in raw
        if not prefix_valid or (
            len(raw) != plan["bytes"] and not expansion_already_started
        ):
            raise RuntimeError(
                f"Original Master Plan prefix changed outside the authorised expansion: {path}"
            )
    return manifest, baseline, inventory


def prompt_lines(manifest: dict[str, Any]) -> list[str]:
    source_path = Path(manifest["sourceContracts"][0]["path"])
    raw = source_path.read_bytes()
    if sha256_bytes(raw).upper() != manifest["sourceContracts"][0]["sha256"].upper():
        raise RuntimeError("Expansion prompt source digest mismatch")
    return raw.decode("utf-8-sig").splitlines()


def plan_chunk(lines: list[str], start_line: int, end_line: int, demote: bool) -> str:
    selected = lines[start_line - 1 : end_line]
    if selected and selected[0].lstrip().startswith("#"):
        selected = selected[1:]
    output = []
    sub_count = 1
    for line in selected:
        if demote and line.startswith("#"):
            match = re.match(r"^##\s+(\d+)\.\s+(.*)$", line)
            if match:
                line = f"## 21.{sub_count} {match.group(2)}"
                sub_count += 1
            elif line.startswith("#"):
                line = "#" + line
        output.append(line)
    return "\n".join(output).strip()


def append_master_plan_sections(
    manifest: dict[str, Any], baseline: dict[str, Any], lines: list[str]
) -> dict[str, Any]:
    additions = {
        PLAN_NAMES[0]: (
            "# 7. MindRoom Product Expansion Retention and Adaptation (2026)",
            plan_chunk(lines, 354, 462, demote=False),
        ),
        PLAN_NAMES[1]: (
            "# 5. MindRoom Product Expansion Removal and Isolation Boundaries (2026)",
            plan_chunk(lines, 463, 550, demote=False),
        ),
        PLAN_NAMES[2]: (
            "# 21. MindRoom Product Expansion Architecture and Execution Plan (2026)",
            plan_chunk(lines, 551, 2184, demote=True),
        ),
    }
    baseline_by_name = {
        Path(item["path"]).name: item for item in baseline["originalMasterPlans"]
    }
    results: dict[str, Any] = {}
    for name, (heading, body) in additions.items():
        path = PLANS / name
        original = path.read_bytes()
        if MARKER.encode("utf-8") not in original:
            note = (
                f"\n{MARKER}\n\n{heading}\n\n"
                f"Run: `{RUN_ID}`\n\n"
                "Preservation status: **ADDITIVE AND CORRECTIVE**. Every original byte above this marker "
                "is preserved. This section supersedes only the prior Graphify-complete claim; it does "
                "not supersede or reduce any original product requirement, safety rule, deletion rule, "
                "verification gate, workflow, or retained AFFiNE capability.\n\n"
                f"{body}\n"
            )
            atomic_write_text(path, original.decode("utf-8-sig") + note)
        new_bytes = path.read_bytes()
        original_info = baseline_by_name[name]
        original_size = original_info["bytes"]
        prefix_preserved = (
            sha256_bytes(new_bytes[:original_size]) == original_info["sha256"]
        )
        if not prefix_preserved:
            raise RuntimeError(f"Original Master Plan prefix not preserved: {name}")
        addition_bytes = new_bytes[original_size:]
        results[name] = {
            "path": graphify_rel(path),
            "originalSha256": original_info["sha256"],
            "newSha256": sha256_bytes(new_bytes),
            "originalBytes": original_size,
            "newBytes": len(new_bytes),
            "originalLineCount": original_info["lineCount"],
            "newLineCount": len(new_bytes.decode("utf-8-sig").splitlines()),
            "addedBytes": len(addition_bytes),
            "additionSha256": sha256_bytes(addition_bytes),
            "originalPrefixPreserved": prefix_preserved,
        }
    return results


def classify_domain(line_number: int, heading: str, text: str) -> str:
    combined = f"{heading} {text}".lower()
    if 616 <= line_number <= 730 or any(word in combined for word in ("canvas", "whiteboard", "edgeless")):
        return "CANVAS"
    if 731 <= line_number <= 862 or "mind map" in combined or "mind-map" in combined:
        return "MIND_MAP"
    if 1080 <= line_number <= 1241 or "calendar" in combined or "event" in combined or "ics" in combined:
        if 1242 <= line_number <= 1452:
            return "FINANCE"
        return "CALENDAR"
    if 1242 <= line_number <= 1475 or any(
        word in combined
        for word in (
            "finance",
            "financial",
            "transaction",
            "transfer",
            "budget",
            "currency",
            "receipt",
            "savings",
            "billing",
            "stripe",
            "revenuecat",
        )
    ):
        return "FINANCE"
    if 863 <= line_number <= 1079 or 2083 <= line_number <= 2117:
        return "KNOWLEDGE"
    if any(word in combined for word in ("relationship", "backlink", "semantic", "stable id", "identity")):
        return "KNOWLEDGE"
    return "KNOWLEDGE"


