def requirement_candidates(lines: list[str]) -> list[dict[str, Any]]:
    ranges = ((354, 1475), (2083, 2117))
    rows: list[dict[str, Any]] = []
    headings: list[tuple[int, str]] = []
    fence = False
    for line_number, raw in enumerate(lines, 1):
        stripped = raw.strip()
        if stripped.startswith("#"):
            level = len(stripped) - len(stripped.lstrip("#"))
            title = stripped[level:].strip()
            while headings and headings[-1][0] >= level:
                headings.pop()
            headings.append((level, title))
        if stripped.startswith("```"):
            fence = not fence
            continue
        if not any(start <= line_number <= end for start, end in ranges):
            continue
        if not stripped or stripped == "---" or stripped.startswith("#"):
            continue
        is_bullet = bool(re.match(r"^\*\s+", stripped))
        relationship_token = (
            2083 <= line_number <= 2112
            and fence
            and bool(re.match(r"^[A-Z][A-Z_]+$", stripped))
        )
        if not (is_bullet or relationship_token or NORMATIVE_RE.search(stripped)):
            continue
        text = re.sub(r"^\*\s+", "", stripped).strip().rstrip(";")
        heading = " > ".join(item[1] for item in headings)
        domain = classify_domain(line_number, heading, text)
        capability_ids = map_requirement_capabilities(domain, text, line_number)
        rows.append(
            {
                "sourceLine": line_number,
                "sourceHeading": heading,
                "text": text,
                "domain": domain,
                "capabilityIds": capability_ids,
            }
        )
    # Explicitly bind the required hierarchy even though the example is fenced.
    hierarchy = [
        "Workspace contains folders, pages, workspace-owned assets, Workspace Home Canvas, workspace mind maps, and the federated Global Knowledge Map.",
        "Folders contain child folders, pages, folder-owned assets, Folder Home Canvas, and folder mind maps.",
        "Pages contain Markdown content, page-owned assets, whiteboards, mind maps, databases, Kanban boards, imports, and exports.",
        "Durable hierarchy relationships use stable identities rather than filesystem paths.",
    ]
    for offset, text in enumerate(hierarchy, 1):
        rows.append(
            {
                "sourceLine": 580 + offset,
                "sourceHeading": "21.1 Required Product Hierarchy",
                "text": text,
                "domain": "KNOWLEDGE",
                "capabilityIds": [f"MR-CAP-{number:03d}" for number in (134, 152, 160)],
            }
        )
    rows.extend(
        [
            {
                "sourceLine": 831,
                "sourceHeading": "10.7 Map-of-maps navigation",
                "text": "The global map must provide map-of-maps navigation into folder clusters and independent maps, return navigation, expansion, collapse, and source-aware filters.",
                "domain": "MIND_MAP",
                "capabilityIds": ["MR-CAP-149"],
            },
            {
                "sourceLine": 1532,
                "sourceHeading": "18.2 Mind-map capability IDs",
                "text": "Mind-Map Projection into Knowledge Graph must remain a distinct traceable capability whose projections preserve source identity and provenance.",
                "domain": "MIND_MAP",
                "capabilityIds": ["MR-CAP-151"],
            },
        ]
    )
    rows.sort(key=lambda row: (row["sourceLine"], row["text"]))
    return rows


