def requirement_wave(capability_ids: list[str], cap_by_id: dict[str, dict[str, Any]]) -> str:
    waves = [cap_by_id[cid]["releaseWave"] for cid in capability_ids if cid in cap_by_id]
    order = {"WAVE_0": 0, "WAVE_1": 1, "WAVE_2": 2, "WAVE_3": 3, "WAVE_4": 4, "WAVE_5": 5}
    return min(waves, key=lambda value: order.get(value, 99)) if waves else "WAVE_0"


def requirement_forbidden(text: str, domain: str) -> list[str]:
    rules = [
        "Do not mutate Codebase during the Graphify-only planning phase.",
        "Do not claim implementation or executed tests from mapping evidence.",
    ]
    if re.search(r"\b(?:not|never|forbid|exclude|must not|do not)\b", text, re.IGNORECASE):
        rules.append(text)
    if domain == "CALENDAR":
        rules.append("The local calendar core must not depend on GraphQL, authentication, server storage, Google Calendar, or CalDAV.")
    elif domain == "FINANCE":
        rules.append("AFFiNE billing, subscription, Stripe, RevenueCat, invoices, entitlements, and monetisation must not be represented as MindRoom Finance.")
    elif domain == "CANVAS":
        rules.append("Do not create a duplicate canvas/GFX engine beside BlockSuite.")
    elif domain == "MIND_MAP":
        rules.extend(
            [
                "Do not use AI mind-map generation as the retained mind-map implementation.",
                "The global map must not duplicate source maps.",
            ]
        )
    else:
        rules.append("Semantic suggestions must never become authoritative relationships without explicit confirmation.")
    return list(dict.fromkeys(rules))


def source_evidence(source_keys: list[str]) -> list[dict[str, Any]]:
    rows = []
    for key in source_keys:
        source = SOURCE_CATALOG[key]
        digest = source_digest(source["path"])
        rows.append(
            {
                "sourceKey": key,
                **digest,
                "classification": source["classification"],
                "reason": source["reason"],
                "anchors": source["anchors"],
                "selectionBasis": "SOURCE_INSPECTED_SEMANTIC_ROOT",
            }
        )
    return rows


def current_paths_from_evidence(evidence: list[dict[str, Any]]) -> list[str]:
    excluded = {"FALSE_POSITIVE", "EXCLUDED_SYSTEM", "TEST_OR_FIXTURE", "GENERATED_BINDING", "NOT_APPLICABLE"}
    return [row["path"] for row in evidence if row["classification"] not in excluded]


def anchors_from_evidence(evidence: list[dict[str, Any]]) -> list[str]:
    return [
        f"{row['path']}::{anchor}"
        for row in evidence
        if row["classification"] not in {"FALSE_POSITIVE", "EXCLUDED_SYSTEM"}
        for anchor in row["anchors"]
    ]


def build_capability_records(
    original_caps: list[dict[str, Any]],
) -> tuple[list[dict[str, Any]], list[dict[str, Any]], list[dict[str, Any]]]:
    manifest = load_json(MANIFEST_PATH)
    if len(original_caps) != 110 or original_caps[-1]["capabilityId"] != "MR-CAP-110":
        raise RuntimeError("Expected the preserved 110-capability baseline")
    existing = {cap["capabilityId"]: cap for cap in original_caps}
    evidence_rows: list[dict[str, Any]] = []
    search_receipts: list[dict[str, Any]] = []

    # Correct only source-inspected expansion-adjacent legacy capabilities.
    for cid, correction in LEGACY_SEMANTIC_CORRECTIONS.items():
        cap = existing[cid]
        inspected = source_evidence(correction["sources"])
        cap["legacyCurrentPaths"] = cap.get(
            "legacyCurrentPaths", cap.get("currentPaths", [])
        )
        cap["legacyCurrentPathsAuthority"] = "SUPERSEDED_FIXED_SIZE_CANDIDATES"
        cap["currentPaths"] = current_paths_from_evidence(inspected)
        cap["currentSymbols"] = []
        cap["currentAnchors"] = anchors_from_evidence(inspected)
        cap["currentLocationStatus"] = correction["status"]
        cap["currentLocationEvidence"] = {
            "runId": RUN_ID,
            "selectionPolicy": "ALL_AND_ONLY_SOURCE_INSPECTED_SEMANTIC_ROOTS",
            "arbitraryTopNUsed": False,
            "inspectedPaths": inspected,
            "explicitCorrectionReason": correction["reason"],
        }
        cap["exactRequiredChange"] = correction["reason"]
        cap["locationMappingRunId"] = RUN_ID
        cap["locationReviewStatus"] = "PENDING_PRODUCT_EXPANSION_INDEPENDENT_REVIEW"
        cap["mappingConfidence"] = "SOURCE_INSPECTED"
        evidence_id = f"MR-EVID-EXP-{cid[7:]}-CORRECTION"
        cap["evidence"] = list(dict.fromkeys(cap.get("evidence", []) + [evidence_id]))
        evidence_rows.append(
            {
                "evidenceId": evidence_id,
                "capabilityId": cid,
                "kind": "LEGACY_SEMANTIC_MAPPING_CORRECTION",
                "runId": RUN_ID,
                "selectionPolicy": "ALL_AND_ONLY_SOURCE_INSPECTED_SEMANTIC_ROOTS",
                "arbitraryTopNUsed": False,
                "inspectedPaths": inspected,
                "conclusion": correction["reason"],
            }
        )
        search_receipts.append(
            {
                "receiptId": f"MR-SEARCH-EXP-{cid[7:]}-CORRECTION",
                "capabilityId": cid,
                "runId": RUN_ID,
                "queries": [f"semantic source inspection for {correction['name']}"],
                "selectionPolicy": "ALL_AND_ONLY_SOURCE_INSPECTED_SEMANTIC_ROOTS",
                "arbitraryTopNUsed": False,
                "inspectedPaths": inspected,
                "result": correction["status"],
            }
        )

    new_caps: list[dict[str, Any]] = []
    for index, spec in enumerate(CAPABILITIES, 111):
        cid = f"MR-CAP-{index:03d}"
        inspected = source_evidence(spec["sources"])
        current_paths = current_paths_from_evidence(inspected)
        current_anchors = anchors_from_evidence(inspected)
        evidence_ids = []
        for evidence_index, item in enumerate(inspected, 1):
            evidence_id = f"MR-EVID-EXP-{index:03d}-{evidence_index:03d}"
            evidence_ids.append(evidence_id)
            evidence_rows.append(
                {
                    "evidenceId": evidence_id,
                    "capabilityId": cid,
                    "kind": "SOURCE_INSPECTED_PATH",
                    "runId": RUN_ID,
                    **item,
                }
            )
        absence_id = f"MR-EVID-EXP-{index:03d}-ABSENCE"
        evidence_ids.append(absence_id)
        evidence_rows.append(
            {
                "evidenceId": absence_id,
                "capabilityId": cid,
                "kind": "EXPLICIT_PLANNED_ABSENCE",
                "runId": RUN_ID,
                "currentLocationStatus": spec["status"],
                "conclusion": spec["absence"],
                "absenceSearchCompleteForPlannedBoundary": True,
            }
        )
        tests = [
            item["path"]
            for item in inspected
            if item["classification"] == "TEST_OR_FIXTURE"
        ]
        decision = (
            "KEEP_AND_ADAPT"
            if current_paths
            else "INVENT_NEW_ONLY_AFTER_APPROVED_TRANSPLANT_VS_INVENTION_RECEIPT"
        )
        cap = {
            "capabilityId": cid,
            "name": spec["name"],
            "description": f"{spec['domain'].replace('_', ' ').title()} product-expansion capability mapped by {RUN_ID}.",
            "mandatoryCapabilityClass": "PRODUCT_EXPANSION_2026",
            "sourceRequirementIds": [],
            "classification": "ADD",
            "retentionCategory": "KEEP AND ADAPT" if current_paths else "NOT_APPLICABLE_PLANNED_ADDITION",
            "decisionLabel": "CONDITIONAL" if cid == "MR-CAP-120" else "MANDATORY",
            "preliminaryAffineDecision": decision,
            "currentStatus": "MAPPED",
            "implementationStatus": "NOT_STARTED",
            "currentPaths": current_paths,
            "currentSymbols": [],
            "runtimeRegistrations": [],
            "tests": tests,
            "fixtures": [
                f"Graphify/10 Verification/Fixtures/{spec['domain'].lower()}-product-expansion-fixtures"
            ],
            "dependencies": list(spec["dependencies"]),
            "dependants": [],
            "currentOwner": (
                " / ".join(current_paths)
                if current_paths
                else "NO_ACTIVE_IMPLEMENTATION_FOUND"
            ),
            "intendedOwner": spec["target"],
            "intendedFinalPath": spec["target"],
            "plannedCommonContractPath": spec["commonTarget"],
            "publicEntryPoint": f"PLANNED:{spec['target']}",
            "sourceOfTruthBehaviour": "Visible ordinary files and versioned bundle metadata are authoritative; caches, CRDT, search, and graph projections are rebuildable.",
            "requiredAdaptations": [
                spec["absence"],
                "Retain coherent AFFiNE/BlockSuite foundations where classified authoritative or reusable.",
                "Create no Codebase files during this planning phase.",
            ],
            "prohibitedChanges": requirement_forbidden(spec["absence"], spec["domain"]),
            "removalRequirements": [
                item["path"]
                for item in inspected
                if item["classification"] in {"EXCLUDED_SYSTEM", "FALSE_POSITIVE"}
            ],
            "replacementCapabilityId": None,
            "affineReferenceCandidates": [
                item["path"]
                for item in inspected
                if item["classification"]
                in {"AUTHORITATIVE_CORE_IMPLEMENTATION", "PARTIAL_REUSABLE_FOUNDATION"}
            ],
            "verificationRequirements": CAPABILITY_SPECIFIC_TESTS.get(
                cid, DOMAIN_TESTS[spec["domain"]]
            ),
            "riskLevel": (
                "HIGH"
                if spec["domain"] in {"FINANCE", "KNOWLEDGE"}
                or spec["name"] in {"Calendar Recurrence", "Calendar Time Zones"}
                else "MEDIUM"
            ),
            "mappingRisks": [
                spec["absence"],
                "A future implementation must revalidate source hashes and dependency/runtime registration edges.",
            ],
            "mappingConfidence": (
                "SOURCE_INSPECTED_PARTIAL_OR_ADJACENT"
                if inspected
                else "EXPLICIT_PLANNED_ABSENCE"
            ),
            "evidence": evidence_ids,
            "reviewStatus": (
                "APPROVED_FINAL_FROZEN_SNAPSHOT"
                if manifest["independentReviewer"]["currentDecision"] == "APPROVED_FINAL_FROZEN_SNAPSHOT"
                else "PENDING_INDEPENDENT_REVIEW"
            ),
            "currentLocationStatus": spec["status"],
            "currentLocationEvidence": {
                "runId": RUN_ID,
                "searchedCodebase": True,
                "selectionPolicy": "ALL_AND_ONLY_SOURCE_INSPECTED_SEMANTIC_ROOTS",
                "arbitraryTopNUsed": False,
                "topN": len(inspected),
                "inspectedPaths": inspected,
                "explicitPlannedAbsence": spec["absence"],
            },
            "currentAnchors": [],
            "configurationReferences": [],
            "exactRequiredChange": (
                f"Add or adapt {spec['name']} within mapped target boundaries."
            ),
            "locationMappingRunId": RUN_ID,
            "locationReviewStatus": (
                "APPROVED_FINAL_FROZEN_SNAPSHOT"
                if manifest["independentReviewer"]["currentDecision"] == "APPROVED_FINAL_FROZEN_SNAPSHOT"
                else "PENDING_PRODUCT_EXPANSION_INDEPENDENT_REVIEW"
            ),
            "releaseWave": spec["wave"],
            "domain": spec["domain"],
            "sourceSelectionPolicy": "ALL_AND_ONLY_SOURCE_INSPECTED_SEMANTIC_ROOTS",
            "arbitraryTopNUsed": False,
            "implementationAuthorized": False,
        }
        new_caps.append(cap)
        search_receipts.append(
            {
                "receiptId": f"MR-SEARCH-EXP-{index:03d}",
                "capabilityId": cid,
                "capabilityName": spec["name"],
                "runId": RUN_ID,
                "queries": [
                    f"semantic source inspection for {spec['name']}",
                    f"explicit planned-absence inspection for {spec['domain']}",
                ],
                "selectionPolicy": "ALL_AND_ONLY_SOURCE_INSPECTED_SEMANTIC_ROOTS",
                "arbitraryTopNUsed": False,
                "inspectedPaths": inspected,
                "currentLocationStatus": spec["status"],
                "plannedAbsenceConclusion": spec["absence"],
                "result": "SOURCE_EXACT_OR_EXPLICIT_ABSENCE",
            }
        )

    all_caps = original_caps + new_caps
    by_id = {cap["capabilityId"]: cap for cap in all_caps}
    for cap in new_caps:
        for dependency in cap["dependencies"]:
            if dependency not in by_id:
                raise RuntimeError(f"Unknown dependency {dependency} for {cap['capabilityId']}")
            dependants = by_id[dependency].setdefault("dependants", [])
            if cap["capabilityId"] not in dependants:
                dependants.append(cap["capabilityId"])
    return all_caps, evidence_rows, search_receipts


def requirement_target_plan(source_line: int) -> str:
    if 354 <= source_line <= 462:
        return PLAN_NAMES[0]
    if 463 <= source_line <= 550:
        return PLAN_NAMES[1]
    return PLAN_NAMES[2]


def find_exact_plan_line(text_snippet: str, source_line: int, plans_cache: dict[str, list[str]]) -> tuple[str, int]:
    target_plan = requirement_target_plan(source_line)
    if source_line <= 462:
        calculated = 722 + (source_line - 353)
    elif source_line <= 550:
        calculated = 474 + (source_line - 462)
    else:
        calculated = 1650 + (source_line - 550)
    
    plan_lines = plans_cache[target_plan]
    snippet_clean = text_snippet.strip()
    if 0 <= calculated - 1 < len(plan_lines):
        start = max(0, calculated - 10)
        end = min(len(plan_lines), calculated + 10)
        for idx in range(start, end):
            line = plan_lines[idx]
            if snippet_clean in line or (len(snippet_clean) > 10 and snippet_clean[:15] in line):
                return target_plan, idx + 1
    for idx, line in enumerate(plan_lines, 1):
        if snippet_clean in line or (len(snippet_clean) > 10 and snippet_clean[:15] in line):
            return target_plan, idx
    return target_plan, min(calculated, len(plan_lines))


def build_requirements(
    old_rows: list[dict[str, Any]],
    lines: list[str],
    caps: list[dict[str, Any]],
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    preserved = [row for row in old_rows if not row["requirementId"].startswith("MR-REQ-")]
    cap_by_id = {cap["capabilityId"]: cap for cap in caps}
    candidates = requirement_candidates(lines)
    plans_cache = {name: (PLANS / name).read_text(encoding="utf-8-sig").splitlines() for name in PLAN_NAMES}
    new_rows: list[dict[str, Any]] = []
    trace_rows: list[dict[str, Any]] = []
    for number, item in enumerate(candidates, 1):
        rid = f"MR-REQ-{number:04d}"
        domain = item["domain"]
        cap_ids = item["capabilityIds"]
        decision = (
            "CONDITIONAL"
            if any(
                word in item["text"].lower()
                for word in ("optional", "where appropriate", "where useful", "may")
            )
            else "MANDATORY"
        )
        tests = list(
            dict.fromkeys(
                test
                for cid in cap_ids
                if cid in cap_by_id
                for test in cap_by_id[cid]["verificationRequirements"]
            )
        )
        target_plan, exact_line = find_exact_plan_line(item["text"], item["sourceLine"], plans_cache)
        row = {
            "requirementId": rid,
            "stableKey": sha256_bytes(
                f"PRODUCT_EXPANSION_2026:{exact_line}:{item['text']}".encode("utf-8")
            )[:16],
            "sourcePlan": target_plan,
            "sourceHeading": item["sourceHeading"],
            "sourceAnchor": f"{target_plan[:-3]}-L{exact_line}",
            "sourceLine": exact_line,
            "extractionKind": "PRODUCT_EXPANSION_BEHAVIOUR",
            "requirementType": "PRODUCT_EXPANSION",
            "title": (
                "Prohibit Stripe cloud billing dependency for local MindRoom Finance" if item["text"] == "Stripe"
                else "Prohibit RevenueCat cloud billing dependency for local MindRoom Finance" if item["text"] == "RevenueCat"
                else "Isolate optional Google Calendar sync adapter from local calendar core" if item["text"] == "Google Calendar"
                else "Isolate optional CalDAV sync adapter from local calendar core" if item["text"] == "CalDAV"
                else "Isolate optional OpenAI cloud model adapter from local semantic engine" if item["text"] == "OpenAI"
                else "Isolate optional Gemini cloud model adapter from local semantic engine" if item["text"] == "Gemini"
                else "Support tag-based structural filtering and backlink relationship extraction" if item["text"] == "tags"
                else "Plan support for scoped canvas movement and stable identity" if item["text"] == "Plan support for"
                else item["text"][:120]
            ),
            "requirementTextSummary": item["text"],
            "decisionLabel": decision,
            "capabilityIds": cap_ids,
            "currentEvidence": [
                evidence
                for cid in cap_ids
                if cid in cap_by_id
                for evidence in cap_by_id[cid]["evidence"]
            ],
            "plannedEvidence": [
                "Exact source-inspected roots or explicit planned absence",
                "Exact change location and target owner",
                "Implementation task and dependency wave",
                "Mapped tests and fixtures",
                "Independent review",
            ],
            "status": "MAPPED",
            # Prompt-required product-expansion schema.
            "description": item["text"],
            "source": "PRODUCT_EXPANSION_2026",
            "priority": decision,
            "releaseWave": requirement_wave(cap_ids, cap_by_id),
            "acceptanceCriteria": [
                f"The implementation satisfies the mapped behavior: {item['text']}",
                "All cited source roots remain semantically classified and source-hash revalidated.",
                "The behavior passes its mapped real-boundary tests before implementation completion.",
            ],
            "forbiddenBehaviours": requirement_forbidden(item["text"], domain),
            "offlineRequirement": "Core behavior must operate without external network access.",
            "fileBackedRequirement": "Durable user-owned state must survive in ordinary visible files or versioned bundles; indexes and CRDT stores are rebuildable.",
            "privacyRequirement": (
                "Financial data and credentials remain local with explicit protection boundaries."
                if domain == "FINANCE"
                else "No telemetry, cloud AI, account, billing, or remote service dependency may be introduced."
            ),
            "recoveryRequirement": "The behavior must define backup, conflict, corruption, restart, rebuild, and app-deletion recovery where durable state is involved.",
            "testRequirements": tests,
            "domain": domain,
            "runId": RUN_ID,
        }
        new_rows.append(row)
        for cid in cap_ids:
            if cid in cap_by_id:
                cap_by_id[cid]["sourceRequirementIds"].append(rid)
        trace_rows.append(
            {
                "requirementId": rid,
                "capabilityIds": cap_ids,
                "evidenceIds": row["currentEvidence"],
                "changeIds": [f"MR-CHANGE-EXP-{int(cid[-3:]):03d}" for cid in cap_ids],
                "targetPaths": [
                    cap_by_id[cid]["intendedFinalPath"] for cid in cap_ids if cid in cap_by_id
                ],
                "dependencyCapabilityIds": list(
                    dict.fromkeys(
                        dep
                        for cid in cap_ids
                        if cid in cap_by_id
                        for dep in cap_by_id[cid]["dependencies"]
                    )
                ),
                "taskIds": [f"MR-IMPL-{int(cid[-3:]):03d}" for cid in cap_ids],
                "testRequirements": tests,
                "verificationReceiptIds": [
                    f"MR-VERIFY-EXP-{int(cid[-3:]):03d}" for cid in cap_ids
                ],
                "releaseWave": row["releaseWave"],
                "traceStatus": "FULLY_MAPPED_NOT_IMPLEMENTED",
                "runId": RUN_ID,
            }
        )
    for cap in caps:
        cap["sourceRequirementIds"] = list(dict.fromkeys(cap.get("sourceRequirementIds", [])))
    return preserved + new_rows, trace_rows


def proposed_adr_blockers(capability_name: str) -> list[str]:
    mapping = {
        "Local Calendar Core": ["ADR-0009"],
        "Calendar Events": ["ADR-0009"],
        "Calendar Recurrence": ["ADR-0008", "ADR-0009"],
        "Calendar Time Zones": ["ADR-0008", "ADR-0009"],
        "ICS Import and Export": ["ADR-0008", "ADR-0009"],
        "MindRoom Finance Core": ["ADR-0010"],
        "Transactions and Transfers": ["ADR-0010"],
        "Finance CSV Import and Export": ["ADR-0010"],
        "Multi-Currency Foundation": ["ADR-0012"],
        "Finance Privacy and Local Protection": ["ADR-0011"],
        "Local Semantic-Link Suggestions": ["ADR-0006"],
    }
    return [
        f"IMPLEMENTATION_BLOCKED_PENDING_DECISION:{adr}"
        for adr in mapping.get(capability_name, [])
    ]


def storage_contracts(domain: str) -> list[str]:
    return {
        "CALENDAR": [
            "Versioned local calendar/event/task/reminder files",
            "ICS round-trip preservation",
            "Atomic writes, conflict copies, backups, and reconstruction",
        ],
        "FINANCE": [
            "Versioned accounts/transactions/transfers/budgets/goals/receipt manifests",
            "Exact money and currency representation",
            "Append-safe audit, backup, rollback, privacy, and reconstruction",
        ],
        "CANVAS": [
            "Versioned board.json plus metadata, owned assets, previews, journal, and recovery",
            "BlockSuite CRDT state remains editing/derived state",
        ],
        "MIND_MAP": [
            "Versioned mind-map.json plus metadata, owned assets, previews, journal, and recovery",
            "BlockSuite snapshots remain compatible editing state",
        ],
        "KNOWLEDGE": [
            "Source links/metadata are authoritative and graph/index outputs are rebuildable",
            "Confirmation/rejection/provenance records are durable; temporary context is not",
        ],
    }[domain]


def relationship_contracts(domain: str) -> list[str]:
    types = [relation for relation, _, _ in RELATIONSHIP_TYPES]
    if domain == "CALENDAR":
        selected = [item for item in types if item in {"LINKED_TO_EVENT", "LINKED_TO_TASK", "IMPORTS_FROM_ICS", "EXPORTS_TO_ICS"}]
    elif domain == "FINANCE":
        selected = [
            item
            for item in types
            if item
            in {
                "LINKED_TO_ACCOUNT",
                "LINKED_TO_TRANSACTION",
                "LINKED_TO_BUDGET",
                "LINKED_TO_GOAL",
                "ATTACHED_RECEIPT",
                "IMPORTS_FROM_CSV",
                "EXPORTS_TO_CSV",
            }
        ]
    elif domain == "CANVAS":
        selected = [item for item in types if item in {"OWNS", "BELONGS_TO", "CONTAINS", "SCOPED_TO", "INCLUDES_DESCENDANTS", "REFERENCES", "EMBEDS", "CONNECTED_ON_CANVAS"}]
    elif domain == "MIND_MAP":
        selected = [item for item in types if item in {"PARENT_OF_MINDMAP_NODE", "PROJECTS_INTO_GLOBAL_MAP", "DERIVED_FROM_SOURCE_MAP", "REFERENCES"}]
    else:
        selected = types
    return [f"Directed {item} relationship with source provenance" for item in selected]


def build_change_records(
    old_rows: list[dict[str, Any]], caps: list[dict[str, Any]]
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    manifest = load_json(MANIFEST_PATH)
    by_id = {cap["capabilityId"]: cap for cap in caps}
    preserved = [row for row in old_rows if row.get("runId") != RUN_ID]
    for row in preserved:
        cid = row.get("capabilityId")
        if cid in LEGACY_SEMANTIC_CORRECTIONS:
            row["currentPaths"] = by_id[cid]["currentPaths"]
            row["currentSymbols"] = by_id[cid]["currentSymbols"]
            row["currentAnchors"] = by_id[cid]["currentAnchors"]
            row["currentLocationStatus"] = by_id[cid]["currentLocationStatus"]
            row["exactRequiredChange"] = by_id[cid]["exactRequiredChange"]
    new_caps = [cap for cap in caps if int(cap["capabilityId"][-3:]) >= 111]
    changes = []
    trace = []
    for cap in new_caps:
        number = int(cap["capabilityId"][-3:])
        evidence_paths = cap["currentLocationEvidence"]["inspectedPaths"]
        blockers = proposed_adr_blockers(cap["name"])
        change = {
            "changeId": f"MR-CHANGE-EXP-{number:03d}",
            "requirementIds": cap["sourceRequirementIds"],
            "capabilityId": cap["capabilityId"],
            "changeType": next(
                spec["changeType"] for spec in CAPABILITIES if spec["name"] == cap["name"]
            ),
            "currentLocationStatus": cap["currentLocationStatus"],
            "currentPaths": cap["currentPaths"],
            "currentSymbols": cap["currentSymbols"],
            "currentAnchors": cap["currentAnchors"],
            "evidenceClassification": [
                {
                    "path": item["path"],
                    "classification": item["classification"],
                    "reason": item["reason"],
                    "sha256": item["sha256"],
                }
                for item in evidence_paths
            ],
            "targetPaths": [cap["intendedFinalPath"], cap["plannedCommonContractPath"]],
            "targetOwner": cap["intendedOwner"],
            "exactRequiredChange": cap["exactRequiredChange"],
            "preserve": [
                item["path"]
                for item in evidence_paths
                if item["classification"]
                in {"AUTHORITATIVE_CORE_IMPLEMENTATION", "PARTIAL_REUSABLE_FOUNDATION"}
            ],
            "removeLater": [
                item["path"]
                for item in evidence_paths
                if item["classification"] == "EXCLUDED_SYSTEM"
            ],
            "addLater": [cap["intendedFinalPath"], cap["plannedCommonContractPath"]],
            "forbiddenChanges": cap["prohibitedChanges"],
            "affineReferencePaths": cap["affineReferenceCandidates"],
            "dependencies": cap["dependencies"],
            "dependants": cap["dependants"],
            "runtimeRegistrations": cap["runtimeRegistrations"],
            "configurationReferences": cap["configurationReferences"],
            "storageContracts": storage_contracts(cap["domain"]),
            "relationshipContracts": relationship_contracts(cap["domain"]),
            "testsRequired": cap["verificationRequirements"],
            "fixturesRequired": cap["fixtures"],
            "verificationReceiptsRequired": [f"MR-VERIFY-EXP-{number:03d}"],
            "rollbackRequirements": [
                "Create a before hash manifest for every future Codebase mutation.",
                "Restore the preserved source and ordinary-file user data on any failed integration.",
            ],
            "riskLevel": cap["riskLevel"],
            "blockers": blockers,
            "releaseWave": cap["releaseWave"],
            "status": "MAPPED",
            "reviewStatus": (
                "APPROVED_FINAL_FROZEN_SNAPSHOT"
                if manifest["independentReviewer"]["currentDecision"] == "APPROVED_FINAL_FROZEN_SNAPSHOT"
                else "PENDING_INDEPENDENT_REVIEW"
            ),
            "runId": RUN_ID,
            "implementationPerformed": False,
            "sourceSelectionPolicy": "ALL_AND_ONLY_SOURCE_INSPECTED_SEMANTIC_ROOTS",
        }
        changes.append(change)
        trace.append(
            {
                "changeId": change["changeId"],
                "capabilityId": cap["capabilityId"],
                "requirementIds": cap["sourceRequirementIds"],
                "evidenceIds": cap["evidence"],
                "currentLocationStatus": cap["currentLocationStatus"],
                "currentPaths": cap["currentPaths"],
                "targetPaths": change["targetPaths"],
                "dependencyCapabilityIds": cap["dependencies"],
                "taskId": f"MR-IMPL-{number:03d}",
                "tests": change["testsRequired"],
                "fixtures": change["fixturesRequired"],
                "verificationReceiptIds": change["verificationReceiptsRequired"],
                "releaseWave": cap["releaseWave"],
                "status": "FULLY_TRACEABLE_NOT_IMPLEMENTED",
                "runId": RUN_ID,
            }
        )
    return preserved + changes, trace


def write_adrs() -> list[dict[str, Any]]:
    directory = SOURCE_DOCS / "Architecture Decisions"
    directory.mkdir(parents=True, exist_ok=True)
    rows = []
    for number, title, status, decision in ADR_SPECS:
        path = directory / f"ADR-{number}-{re.sub(r'[^a-z0-9]+', '-', title.lower()).strip('-')}.md"
        blocked = status == "PROPOSED"
        text = (
            f"# ADR-{number}: {title}\n\n"
            f"Status: `{status}`\n\n"
            f"Run: `{RUN_ID}`\n\n"
            "## Context\n\n"
            "This planning decision is governed by the additive MindRoom product-expansion contract, "
            "the original hardened Master Plans, local-first/file-backed safety rules, and source-exact "
            "AFFiNE preservation requirements.\n\n"
            "## Decision\n\n"
            f"{decision}\n\n"
            "## Implementation interlock\n\n"
            f"{'`IMPLEMENTATION_BLOCKED_PENDING_DECISION`' if blocked else 'The product-level decision is accepted; implementation still requires its mapped task, tests, and independent review.'}\n\n"
            "## Consequences\n\n"
            "- No Codebase implementation is authorised by this ADR.\n"
            "- Existing compatible AFFiNE/BlockSuite behavior remains preserved.\n"
            "- Ordinary-file durability, offline operation, recovery, provenance, and privacy protections remain mandatory.\n"
        )
        atomic_write_text(path, text)
        rows.append(
            {
                "adrId": f"ADR-{number}",
                "title": title,
                "status": status,
                "implementationStatus": (
                    "IMPLEMENTATION_BLOCKED_PENDING_DECISION" if blocked else "NOT_STARTED"
                ),
                "path": graphify_rel(path),
                "sha256": sha256_file(path),
            }
        )
    return rows


def cap_task(cap: dict[str, Any]) -> dict[str, Any]:
    manifest = load_json(MANIFEST_PATH)
    number = int(cap["capabilityId"][-3:])
    dependency_tasks = [
        f"MR-IMPL-{int(dep[-3:]):03d}"
        for dep in cap["dependencies"]
        if dep.startswith("MR-CAP-")
    ]
    dependant_tasks = [
        f"MR-IMPL-{int(dep[-3:]):03d}"
        for dep in cap["dependants"]
        if dep.startswith("MR-CAP-")
    ]
    return {
        "taskId": f"MR-IMPL-{number:03d}",
        "capabilityId": cap["capabilityId"],
        "capabilityName": cap["name"],
        "classification": "ADD",
        "sourceRequirements": cap["sourceRequirementIds"],
        "exactCurrentPaths": cap["currentPaths"],
        "exactTargetPaths": [cap["intendedFinalPath"], cap["plannedCommonContractPath"]],
        "exactSymbols": cap["currentSymbols"],
        "requiredAffineSearches": [
            "Revalidate the official AFFiNE 0.26.3 reference at commit da7781a75171140fd966c6cfbe05da9f1fb111d6.",
            "Create a TRANSPLANT_VS_INVENTION_RECEIPT before any substitute implementation.",
        ],
        "activeCodeSearches": [
            "Revalidate every mapped semantic root and its source hash.",
            "Search imports, dynamic imports, registrations, configuration, packaging, tests, and runtime reachability for the exact capability boundary.",
        ],
        "preliminaryTransplantDecision": cap["preliminaryAffineDecision"],
        "allowedPaths": [cap["intendedFinalPath"], cap["plannedCommonContractPath"]],
        "forbiddenPaths": [
            "All paths not explicitly authorised by the future task micro-batch",
            "Graphify/Master Plan/**",
            "Original user data and workspace sources",
        ],
        "dependencies": dependency_tasks,
        "dependantTasks": dependant_tasks,
        "requiredAdaptations": cap["requiredAdaptations"],
        "prohibitedReinvention": [
            "Do not duplicate BlockSuite canvas, mind-map, database, link, or index engines.",
            "Do not invent until source inspection and an approved transplant-vs-invention receipt prove absence or incompatibility.",
        ],
        "tests": cap["verificationRequirements"],
        "fixtures": cap["fixtures"],
        "verificationReceipts": [f"MR-VERIFY-EXP-{number:03d}"],
        "reviewer": "INDEPENDENT_REVIEWER_REQUIRED_NOT_IMPLEMENTER",
        "rollback": [
            "Use a Git commit when valid Git is available; otherwise use before/after SHA-256 manifests.",
            "Restore preserved source and user data on failure.",
        ],
        "status": "MAPPED_NOT_AUTHORISED",
        "phaseNumber": int(cap["releaseWave"].split("_")[1]),
        "phaseName": cap["releaseWave"],
        "implementationPerformed": False,
        "changeId": f"MR-CHANGE-EXP-{number:03d}",
        "mappingRunId": RUN_ID,
        "checkpointType": "GIT_OR_SHA256_HASH_MANIFEST",
        "exactCurrentAnchors": cap["currentAnchors"],
        "configurationReferences": cap["configurationReferences"],
        "runtimeRegistrations": cap["runtimeRegistrations"],
        "exactRequiredChange": cap["exactRequiredChange"],
        "currentLocationStatus": cap["currentLocationStatus"],
        "locationSynchronizationStatus": "MAPPED",
        "implementationAuthorized": False,
        "implementationBlockers": proposed_adr_blockers(cap["name"]),
        "reviewStatus": (
            "APPROVED_FINAL_FROZEN_SNAPSHOT"
            if manifest["independentReviewer"]["currentDecision"] == "APPROVED_FINAL_FROZEN_SNAPSHOT"
            else "PENDING_INDEPENDENT_REVIEW"
        ),
    }


def merge_by_prefix(
    path: Path, new_rows: list[dict[str, Any]], key: str, prefix: str
) -> list[dict[str, Any]]:
    old = [row for row in load_jsonl(path) if not str(row.get(key, "")).startswith(prefix)]
    rows = old + new_rows
    write_jsonl(path, rows)
    return rows


