def current_codebase_state(baseline: dict[str, Any]) -> dict[str, Any]:
    rows = []
    for path in sorted(p for p in CODEBASE.rglob("*") if p.is_file()):
        rows.append(
            {
                "path": "Codebase/" + path.relative_to(CODEBASE).as_posix(),
                "sizeBytes": path.stat().st_size,
                "sha256": sha256_file(path),
            }
        )
    directories = [
        "Codebase/"
        + (path.relative_to(CODEBASE).as_posix() + "/" if path != CODEBASE else "")
        for path in [CODEBASE] + sorted(p for p in CODEBASE.rglob("*") if p.is_dir())
    ]
    canonical_files = "".join(
        f"{row['path']}\0{row['sizeBytes']}\0{row['sha256']}\n" for row in rows
    )
    canonical_dirs = "".join(f"{path}\n" for path in directories)
    baseline_files = {
        row["path"]: (row["sizeBytes"], row["sha256"])
        for row in baseline["codebase"]["files"]
    }
    current_files = {
        row["path"]: (row["sizeBytes"], row["sha256"]) for row in rows
    }
    modified = sorted(
        path
        for path in baseline_files.keys() & current_files.keys()
        if baseline_files[path] != current_files[path]
    )
    added = sorted(current_files.keys() - baseline_files.keys())
    removed = sorted(baseline_files.keys() - current_files.keys())
    return {
        "fileCount": len(rows),
        "directoryCount": len(directories),
        "fileTreeSha256": sha256_bytes(canonical_files.encode("utf-8")),
        "directoryTreeSha256": sha256_bytes(canonical_dirs.encode("utf-8")),
        "modifiedFiles": modified,
        "addedFiles": added,
        "removedFiles": removed,
        "unchanged": not (modified or added or removed)
        and len(directories) == baseline["codebase"]["directoryCount"]
        and sha256_bytes(canonical_files.encode("utf-8"))
        == baseline["codebase"]["fileTreeSha256"]
        and sha256_bytes(canonical_dirs.encode("utf-8"))
        == baseline["codebase"]["directoryTreeSha256"],
    }


def semantic_gate_evidence(
    gate: str,
    path_map: dict[str, list[Path]],
) -> list[dict[str, Any]]:
    domain = "knowledge"
    if gate.startswith("calendar") or "Calendar" in gate:
        domain = "calendar"
    elif gate.startswith("finance") or "Finance" in gate:
        domain = "finance"
    elif gate.startswith("canvas") or "Canvas" in gate or "whiteboard" in gate:
        domain = "canvas"
    elif "mindMap" in gate or "MindMap" in gate or "mapDuplication" in gate:
        domain = "mindmap"
    elif gate.startswith("original") or gate.startswith("noRequirement") or gate.startswith("noUnauthorized"):
        domain = "preservation"
    elif gate in {"codebaseUnmodified", "finalReleaseReceiptLocked"}:
        domain = "control"
    elif gate in {
        "allNewRequirementsTraceable",
        "allNewCapabilitiesTraceable",
        "allNewChangesHaveExactTargets",
        "allNewTestsMapped",
        "releaseWavesUpdated",
        "oldCompletionSuperseded",
        "allDerivedArtifactsRegenerated",
        "independentReviewPassed",
    }:
        domain = "completion"
    return [
        {
            "path": graphify_rel(path),
            "sha256": sha256_file(path),
        }
        for path in path_map[domain]
        if path.exists()
    ]


def update_verification(
    caps: list[dict[str, Any]],
    requirements: list[dict[str, Any]],
    plan_results: dict[str, Any],
    baseline: dict[str, Any],
    codebase_after: dict[str, Any],
) -> dict[str, Any]:
    cap_by_id = {cap["capabilityId"]: cap for cap in caps}
    old_tests = [
        row
        for row in load_jsonl(VERIFICATION / "REQUIREMENT_TEST_MATRIX.jsonl")
        if not row["requirementId"].startswith("MR-REQ-")
    ]
    new_tests = []
    for requirement in requirements:
        if not requirement["requirementId"].startswith("MR-REQ-"):
            continue
        cap_ids = requirement["capabilityIds"]
        new_tests.append(
            {
                "requirementId": requirement["requirementId"],
                "requirementType": "PRODUCT_EXPANSION",
                "capabilityIds": cap_ids,
                "capabilityNames": [cap_by_id[cid]["name"] for cid in cap_ids],
                "testTypes": [
                    "STATIC_TRACE",
                    "UNIT",
                    "REAL_FILESYSTEM_INTEGRATION",
                    "OFFLINE_INTEGRATION",
                    "RESTART_RECOVERY",
                    "DESKTOP_E2E",
                    "APP_DELETION_RECONSTRUCTION",
                ],
                "commandIds": [
                    "CMD-TEST-DISCOVERY",
                    "CMD-BLOCKSUITE-UNIT",
                    "CMD-DESKTOP-E2E",
                    "CMD-PRODUCT-EXPANSION-FUTURE",
                ],
                "requiredFixtures": list(
                    dict.fromkeys(
                        fixture
                        for cid in cap_ids
                        for fixture in cap_by_id[cid]["fixtures"]
                    )
                ),
                "requiredRealBoundaries": [
                    "DISPOSABLE_REAL_FILESYSTEM",
                    "NETWORK_DISABLED",
                    "PROCESS_RESTART",
                    "APP_STORAGE_REMOVAL_WITH_USER_FILES_PRESERVED",
                ],
                "mockSufficiency": "MOCKS_INSUFFICIENT_FOR_DURABILITY_PRIVACY_AND_RECOVERY",
                "mappingStatus": "MAPPED_NOT_EXECUTED",
                "verificationStatus": "NOT_VERIFIED",
                "evidenceReceiptIds": [
                    f"MR-VERIFY-EXP-{int(cid[-3:]):03d}" for cid in cap_ids
                ],
                "releaseGateImpact": "BLOCKING_FUTURE_IMPLEMENTATION_COMPLETION",
                "source": {
                    "plan": requirement["sourcePlan"],
                    "heading": requirement["sourceHeading"],
                    "line": requirement["sourceLine"],
                },
                "releaseWave": requirement["releaseWave"],
                "runId": RUN_ID,
            }
        )
    write_jsonl(
        VERIFICATION / "REQUIREMENT_TEST_MATRIX.jsonl", old_tests + new_tests
    )

    fixture_lines = [
        "# Product Expansion Fixture and QA Matrix",
        "",
        f"Run: `{RUN_ID}`",
        "",
        "**Mapped only; no test execution is claimed.**",
        "",
        "| Capability | Domain | Required tests | Required fixtures |",
        "|---|---|---|---|",
    ]
    for cap in caps:
        if int(cap["capabilityId"][-3:]) < 111:
            continue
        fixture_lines.append(
            f"| {cap['capabilityId']} {cap['name']} | {cap['domain']} | "
            f"{'<br>'.join(cap['verificationRequirements'])} | {'<br>'.join(cap['fixtures'])} |"
        )
    fixture_lines.extend(
        [
            "",
            "Required destructive/recovery fixtures use disposable copies only. Calendar fixtures include DST, recurrence exceptions, ICS round trips, reminders, all-day events, and optional adapter failure. Finance fixtures include exact money, transfers, duplicate CSV imports, corrupt/reordered rows, multi-currency, receipt ownership, and privacy boundaries. Canvas and mind-map fixtures include nested ownership, movement, previews/assets, corruption, source-map federation, and non-duplication. Knowledge fixtures include explicit/backlink derivation, semantic false positives, rejected suggestions, provenance, temporary context, stable-ID moves, and full reconstruction.",
            "",
        ]
    )
    atomic_write_text(VERIFICATION / "FIXTURE_QA_MATRIX.md", "\n".join(fixture_lines))

    release = load_json(VERIFICATION / "RELEASE_GATE_MATRIX.json")
    # Preserve the original application-release gates byte-semantically: all remain locked.
    if len(release["gates"]) != 37 or any(
        gate["status"] != "NOT_VERIFIED" for gate in release["gates"]
    ):
        raise RuntimeError("Original final application release gates are not locked")
    path_map = {
        "calendar": [
            CAPMAP / "CAPABILITY_REGISTRY.json",
            CAPMAP / "CAPABILITY_EVIDENCE.jsonl",
            VERIFICATION / "FIXTURE_QA_MATRIX.md",
        ],
        "finance": [
            CAPMAP / "CAPABILITY_REGISTRY.json",
            CAPMAP / "CAPABILITY_EVIDENCE.jsonl",
            VERIFICATION / "FIXTURE_QA_MATRIX.md",
        ],
        "canvas": [
            CAPMAP / "CAPABILITY_REGISTRY.json",
            OWNERSHIP / "FOLDER_OWNERSHIP_MATRIX.json",
            VERIFICATION / "FIXTURE_QA_MATRIX.md",
        ],
        "mindmap": [
            CAPMAP / "CAPABILITY_REGISTRY.json",
            CAPMAP / "CAPABILITY_EVIDENCE.jsonl",
            KG / "CAPABILITY_DEPENDENCY_GRAPH.json",
        ],
        "knowledge": [
            KG / "CAPABILITY_DEPENDENCY_GRAPH.json",
            CAPMAP / "REQUIREMENT_TRACEABILITY_MATRIX.jsonl",
            LOCATIONS / "CHANGE_TRACEABILITY_MATRIX.jsonl",
        ],
        "preservation": [INVENTORY_PATH, PRESERVATION_REPORT_PATH],
        "control": [BASELINE_PATH, COMPLETION / "FINAL_RELEASE_RECEIPT.json"],
        "completion": [
            CAPMAP / "REQUIREMENT_TRACEABILITY_MATRIX.jsonl",
            LOCATIONS / "CHANGE_TRACEABILITY_MATRIX.jsonl",
            IMPLEMENTATION / "IMPLEMENTATION_TASKS.jsonl",
            VERIFICATION / "REQUIREMENT_TEST_MATRIX.jsonl",
        ],
    }
    gate_records = []
    for gate in SEMANTIC_GATES:
        passed = gate != "independentReviewPassed"
        gate_records.append(
            {
                "gate": gate,
                "status": "PASS" if passed else "PENDING_INDEPENDENT_REVIEW",
                "value": passed,
                "evidence": semantic_gate_evidence(gate, path_map),
                "runId": RUN_ID,
            }
        )
    product_validation = {
        "schemaVersion": 1,
        "project": "MindRoom",
        "runId": RUN_ID,
        "generatedAt": now_utc(),
        "status": "READY_FOR_INDEPENDENT_REVIEW",
        "gateCount": len(gate_records),
        "passedGateCount": sum(row["value"] for row in gate_records),
        "allGatesPassed": all(row["value"] for row in gate_records),
        "gates": gate_records,
        "masterPlanHashes": {
            name: plan_results[name]["newSha256"] for name in PLAN_NAMES
        },
        "codebaseBefore": baseline["codebase"],
        "codebaseAfter": codebase_after,
        "implementationPerformed": False,
    }
    write_json(PRODUCT_VALIDATION_PATH, product_validation)
    release.update(
        {
            "generatedAt": now_utc(),
            "runId": RUN_ID,
            "status": "APPLICATION_RELEASE_LOCKED_PRODUCT_EXPANSION_MAPPING_ONLY",
            "allGatesPassed": False,
            "completionBannerUnlocked": False,
            "gateCount": 37,
            "productExpansionSemanticGateCount": len(gate_records),
            "productExpansionSemanticGatesPath": graphify_rel(PRODUCT_VALIDATION_PATH),
            "productExpansionSemanticGatesSha256": sha256_file(PRODUCT_VALIDATION_PATH),
            "applicationImplementationPerformed": False,
            "finalReleaseReceiptLocked": True,
        }
    )
    write_json(VERIFICATION / "RELEASE_GATE_MATRIX.json", release)

    offline = [
        "# Offline Test Plan",
        "",
        f"Product-expansion mapping run: `{RUN_ID}`",
        "",
        "No tests were executed. Future implementation must prove every local core with the network disabled:",
        "",
        "- calendar CRUD, recurrence, reminders, tasks, journal projection, ownership, and ICS round trips;",
        "- accounts, transactions, transfers, budgets, recurring bills/income, goals, receipts, exact money, CSV, and dashboards;",
        "- folder/workspace canvas ownership, BlockSuite editing, movement, file bundles, assets, previews, and recovery;",
        "- independent/folder/workspace mind maps and a federated non-duplicating global projection;",
        "- structural links, explicit links/backlinks, confirmed/rejected semantic suggestions, manual links, temporary context separation, filters, and provenance;",
        "- stable identities, watchers, conflicts, corruption recovery, reconstruction, and app deletion.",
        "",
        "Google Calendar, CalDAV, GraphQL, billing, subscription, cloud AI, and embedding services are never required for local-core success.",
        "",
    ]
    atomic_write_text(VERIFICATION / "OFFLINE_TEST_PLAN.md", "\n".join(offline))
    deletion = [
        "# App-Deletion Survival Test Plan",
        "",
        f"Product-expansion mapping run: `{RUN_ID}`",
        "",
        "No destructive test was executed. Future tests use a disposable workspace and must:",
        "",
        "1. create representative calendar, finance, canvas, mind-map, relationship, identity, asset, receipt, and provenance data;",
        "2. flush ordinary visible files/bundles plus backups and conflict copies;",
        "3. record a complete content/hash manifest;",
        "4. remove only application-managed derived state and the disposable application installation;",
        "5. reinstall a clean build without network access;",
        "6. reconstruct indexes, backlinks, global graph projections, previews, reminders, derived calendar-finance projections, and local map federation;",
        "7. prove stable IDs and cross-object links survive file/folder movement;",
        "8. compare user-owned source files byte-for-byte and semantic views field-for-field;",
        "9. preserve rejected semantic suggestions and never promote temporary context;",
        "10. emit an independent verification receipt.",
        "",
        "Failure must preserve the source workspace and produce recoverable diagnostics; it must never overwrite the only good copy.",
        "",
    ]
    atomic_write_text(
        VERIFICATION / "APP_DELETION_SURVIVAL_TEST_PLAN.md", "\n".join(deletion)
    )
    return {
        "requirementTestRows": len(old_tests) + len(new_tests),
        "newRequirementTestRows": len(new_tests),
        "semanticGates": len(gate_records),
        "semanticGatesPassed": sum(row["value"] for row in gate_records),
    }


def preserve_historical_completion() -> dict[str, str]:
    historical = COMPLETION / "Historical" / PREVIOUS_RUN
    historical.mkdir(parents=True, exist_ok=True)
    sources = {
        "GRAPHIFY_MAPPING_RECEIPT.json": COMPLETION / "GRAPHIFY_MAPPING_RECEIPT.json",
        "GLOBAL_VALIDATION_RESULT.json": COMPLETION / "GLOBAL_VALIDATION_RESULT.json",
        "status.json": CONTROL / "status.json",
        "STATUS.json": CONTROL / "STATUS.json",
    }
    hashes = {}
    for name, source in sources.items():
        target = historical / name
        if not target.exists():
            copy_file(source, target)
        hashes[name] = sha256_file(target)
    record = {
        "schemaVersion": 1,
        "priorRunId": PREVIOUS_RUN,
        "historicalEvidencePreserved": True,
        "historicalArtifacts": [
            {
                "path": graphify_rel(historical / name),
                "sha256": digest,
            }
            for name, digest in hashes.items()
        ],
        "priorMappingCompletionClaim": "SUPERSEDED_ONLY_BY_AUTHORISED_PRODUCT_EXPANSION",
        "originalMasterPlanContentSuperseded": False,
        "reason": "The previous mapping receipt predates 51 new product capabilities and their requirements.",
        "runId": RUN_ID,
        "recordedAt": now_utc(),
    }
    write_json(historical / "SUPERSESSION_RECORD.json", record)
    return hashes


