def update_status_and_execution_manifest(
    manifest: dict[str, Any],
    plan_results: dict[str, Any],
    codebase_after: dict[str, Any],
) -> None:
    status = {
        "project": "MindRoom",
        "schemaVersion": 2,
        "projectPhase": "GRAPHIFY_MAPPING",
        "currentBatchId": None,
        "currentTaskId": None,
        "lastCompletedTaskId": "product-expansion-primary-generation",
        "lastUpdatedAt": now_utc(),
        "repositoryRoot": str(PROJECT.resolve()),
        "codebaseRoot": str(CODEBASE.resolve()),
        "graphifyRoot": str(GRAPHIFY.resolve()),
        "gitStatus": "MISSING",
        "graphifyStatus": "AVAILABLE",
        "ponytailStatus": "AVAILABLE",
        "subagentStatus": "AVAILABLE",
        "releaseGateStatus": "LOCKED",
        "runId": RUN_ID,
        "codebaseBaseline": codebase_after["fileTreeSha256"],
        "masterPlanHashes": {
            name: plan_results[name]["newSha256"] for name in PLAN_NAMES
        },
        "mappingStatus": "READY_FOR_INDEPENDENT_REVIEW",
        "productExpansion": {
            "previousCapabilityCount": 110,
            "capabilityCount": 161,
            "independentReviewStatus": "PENDING",
            "openMappingBlockers": [],
            "implementationPerformed": False,
            "codebaseUnmodified": codebase_after["unchanged"],
            "oldCompletionSuperseded": True,
            "finalReleaseReceiptLocked": True,
        },
    }
    write_json(CONTROL / "status.json", status)
    authority = {
        "schemaVersion": 1,
        "project": "MindRoom",
        "runId": RUN_ID,
        "canonicalStatusPath": "Graphify/00 Execution Control/status.json",
        "canonicalStatusSha256": sha256_file(CONTROL / "status.json"),
        "duplicateStatusFiles": [
            {
                "path": "Graphify/00 Execution Control/STATUS.json",
                "classification": "LEGACY_NON_AUTHORITATIVE",
                "mutationPolicy": "PRESERVE_HISTORICAL_EVIDENCE_DO_NOT_USE_FOR_CURRENT_STATE",
                "sha256": sha256_file(CONTROL / "STATUS.json"),
            }
        ],
        "authorityRule": "Only the lowercase status.json mandated by the Master Plan controls current execution state.",
    }
    write_json(CONTROL / "STATUS_AUTHORITY.json", authority)

    manifest["status"] = "PRIMARY_ARTIFACTS_GENERATED_PENDING_VALIDATION_AND_REVIEW"
    manifest["lastUpdatedAt"] = now_utc()
    manifest["historicalCompletion"][
        "priorMappingCompletionClaim"
    ] = "SUPERSEDED_ONLY_BY_CURRENT_PRODUCT_EXPANSION"
    manifest["historicalCompletion"]["originalMasterPlanContentSuperseded"] = False
    for phase in manifest["phaseLedger"]:
        if phase["phase"] == "MASTER_PLAN_EXPANSION":
            phase["status"] = "COMPLETE"
        elif phase["phase"] == "DERIVED_ARTIFACT_REGENERATION":
            phase["status"] = "COMPLETE"
        elif phase["phase"] == "INDEPENDENT_REVIEW":
            phase["status"] = "PENDING"
    manifest["preservationGuardrail"]["requiredPostEditReport"].update(
        {
            "complete": True,
            "sha256": sha256_file(PRESERVATION_REPORT_PATH),
        }
    )
    manifest["currentMasterPlanHashes"] = {
        name: plan_results[name]["newSha256"] for name in PLAN_NAMES
    }
    manifest["codebaseAfter"] = codebase_after
    manifest["mutationInterlocks"].update(
        {
            "masterPlanMutationAuthorized": False,
            "codebaseMutationAuthorized": False,
            "finalReleaseAuthorized": False,
        }
    )
    write_json(MANIFEST_PATH, manifest)
    event = {
        "eventId": stable_id("MR-EVENT", RUN_ID, "PRIMARY_GENERATION"),
        "timestamp": now_utc(),
        "runId": RUN_ID,
        "event": "PRIMARY_PRODUCT_EXPANSION_GENERATED",
        "status": "PENDING_VALIDATION_AND_INDEPENDENT_REVIEW",
        "codebaseUnmodified": codebase_after["unchanged"],
    }
    old_events = [
        row for row in load_jsonl(EVENTS_PATH) if row.get("eventId") != event["eventId"]
    ]
    write_jsonl(EVENTS_PATH, old_events + [event])


def update_authoritative_artifact_manifest(
    plan_results: dict[str, Any],
    codebase_after: dict[str, Any],
) -> dict[str, Any]:
    path = CONTROL / "AUTHORITATIVE_V2_ARTIFACT_MANIFEST.json"
    old = load_json(path)
    old_paths = [
        item["path"]
        for item in old.get("artifacts", [])
        if item["path"] != graphify_rel(path)
    ]
    required = [
        f"Graphify/Master Plan/{name}" for name in PLAN_NAMES
    ] + [
        "Graphify/00 Execution Control/PRODUCT_EXPANSION_MANIFEST.json",
        "Graphify/00 Execution Control/PRODUCT_EXPANSION_BASELINE.json",
        "Graphify/00 Execution Control/STATUS_AUTHORITY.json",
        "Graphify/03 Capability Map/CAPABILITY_REGISTRY.json",
        "Graphify/03 Capability Map/REQUIREMENT_REGISTRY.jsonl",
        "Graphify/03 Capability Map/REQUIREMENT_TRACEABILITY_MATRIX.jsonl",
        "Graphify/03 Capability Map/CAPABILITY_SOURCE_SEARCH_RECEIPTS.jsonl",
        "Graphify/03 Capability Map/CAPABILITY_EVIDENCE.jsonl",
        "Graphify/04 Exact Location Registry/EXACT_LOCATION_REGISTRY.json",
        "Graphify/04 Exact Location Registry/EXACT_LOCATION_COVERAGE.json",
        "Graphify/04 Exact Location Registry/CHANGE_LOCATION_REGISTRY.jsonl",
        "Graphify/04 Exact Location Registry/CHANGE_TRACEABILITY_MATRIX.jsonl",
        "Graphify/05 Dependency and Impact/CAPABILITY_DEPENDENCY_GRAPH.json",
        "Graphify/05 Dependency and Impact/Knowledge Graph/NODES.jsonl",
        "Graphify/05 Dependency and Impact/Knowledge Graph/EDGES.jsonl",
        "Graphify/05 Dependency and Impact/Knowledge Graph/graph.json",
        "Graphify/06 Folder Ownership/FOLDER_OWNERSHIP_MATRIX.json",
        "Graphify/06 Folder Ownership/CAPABILITY_TO_PATH_MAP.json",
        "Graphify/07 Reorganisation/REORGANISATION_LEDGER.jsonl",
        "Graphify/09 Implementation/IMPLEMENTATION_TASKS.jsonl",
        "Graphify/10 Verification/REQUIREMENT_TEST_MATRIX.jsonl",
        "Graphify/10 Verification/RELEASE_GATE_MATRIX.json",
        "Graphify/11 Completion/PRODUCT_EXPANSION_VALIDATION_GATES.json",
        "Graphify/15 Processed Plan Snapshots/MASTER_PLAN_MANIFEST.json",
        "Graphify/15 Processed Plan Snapshots/MASTER_PLAN_PRESERVATION_REPORT.json",
    ]
    paths = sorted(set(old_paths + required))
    artifacts = []
    for rel in paths:
        candidate = PROJECT / rel
        if not candidate.is_file():
            continue
        artifacts.append(
            {
                "path": rel,
                "sha256": sha256_file(candidate),
                "sizeBytes": candidate.stat().st_size,
                "provenance": (
                    "PRODUCT_EXPANSION_REGENERATED"
                    if rel in required
                    else "VERIFIED_CARRY_FORWARD_UNAFFECTED_OR_HISTORICAL"
                ),
            }
        )
    manifest = {
        "schemaVersion": "mindroom.graphify.authoritative-v2-artifact-manifest.v2",
        "runId": RUN_ID,
        "codebaseBaselineSha256": codebase_after["fileTreeSha256"],
        "masterPlanHashes": {
            name: plan_results[name]["newSha256"] for name in PLAN_NAMES
        },
        "graphBuilderPath": graphify_rel(Path(__file__)),
        "graphBuilderSha256": sha256_file(Path(__file__)),
        "graphBuilderGeneratorVersion": "mindroom-product-expansion-v1",
        "graphifyExtractorVersion": "graphifyy==0.9.28 (source graph carried forward)",
        "extractionPolicyVersion": "semantic-source-roots-no-fixed-top-n-v1",
        "generatedAt": now_utc(),
        "authoritativeRoots": old["authoritativeRoots"],
        "artifactCount": len(artifacts),
        "artifacts": artifacts,
        "selfHashPolicy": "This manifest excludes itself.",
        "excludedScopes": old.get("excludedScopes", []),
        "legacyAndCacheHistoryPolicy": "Preserved as historical/non-authoritative evidence unless explicitly listed as regenerated.",
        "statusAuthority": "Graphify/00 Execution Control/status.json",
        "codebaseUnmodified": codebase_after["unchanged"],
    }
    write_json(path, manifest)
    return manifest


